"""Core logic for the Best Book Awards feature."""

import logging

from openlibrary.core import db
from openlibrary.core.bookshelves import Bookshelves

logger = logging.getLogger(__name__)


class Bestbook(db.CommonExtras):
    """Provides Best Book Award operations for Open Library."""

    TABLENAME = "bestbook_awards"
    PRIMARY_KEY = ("username", "work_id")

    class AwardConditionsError(Exception):
        """Exception raised when award conditions are not met."""
        pass

    @classmethod
    def prepare_query(
        cls,
        select="*",
        work_id=None,
        username=None,
        topic=None,
    ):
        """Builds the SQL query string and its bound variables for fetching
        awards matching the specified filters."""
        query = f"SELECT {select} FROM {cls.TABLENAME}"
        where_clauses = []
        data = {}

        if work_id is not None:
            where_clauses.append("work_id = $work_id")
            data["work_id"] = work_id
        if username is not None:
            where_clauses.append("username = $username")
            data["username"] = username
        if topic is not None:
            where_clauses.append("topic = $topic")
            data["topic"] = topic

        if where_clauses:
            query += " WHERE " + " AND ".join(where_clauses)

        return query, data

    @classmethod
    def get_awards(cls, work_id=None, username=None, topic=None):
        """Returns the list of best book awards matching the specified filters
        (any combination of work_id, username, topic)."""
        query, data = cls.prepare_query(
            work_id=work_id, username=username, topic=topic
        )
        return list(db.get_db().query(query, vars=data))

    @classmethod
    def get_count(cls, work_id=None, username=None, topic=None):
        """Returns the count of best book awards matching the specified filters."""
        query, data = cls.prepare_query(
            select="COUNT(*)", work_id=work_id, username=username, topic=topic
        )
        result = db.get_db().query(query, vars=data)
        return result[0] if result else 0

    @classmethod
    def add(
        cls,
        username: str,
        work_id: str,
        topic: str,
        comment: str = "",
        edition_id: int | None = None,
    ) -> int | None:
        """Adds an award when conditions are met, otherwise raises
        Bestbook.AwardConditionsError."""
        # Validate that the patron has marked the work as "Already Read"
        if not Bookshelves.user_has_read_work(username, work_id):
            raise cls.AwardConditionsError(
                "Only books which have been marked as read may be given awards"
            )

        # Check for duplicate nomination for the same work
        existing = cls.get_awards(username=username, work_id=work_id)
        if existing:
            raise cls.AwardConditionsError(
                f"Work {work_id} has already been nominated by {username}"
            )

        # Check for duplicate topic used for a different work
        existing_topic = cls.get_awards(username=username, topic=topic)
        if existing_topic:
            raise cls.AwardConditionsError(
                f"Topic '{topic}' has already been used by {username}"
            )

        return db.get_db().insert(
            cls.TABLENAME,
            username=username,
            work_id=work_id,
            topic=topic,
            comment=comment,
            edition_id=edition_id,
        )

    @classmethod
    def remove(cls, username: str, work_id: str | None = None, topic: str | None = None) -> int:
        """Removes any award for the username where the work_id or topic matches."""
        query, data = cls.prepare_query(
            work_id=work_id, username=username, topic=topic
        )
        where_clause = " AND ".join(
            [
                f"username = '${username}'"
            ]
            + ([f"work_id = '${work_id}'"] if work_id else [])
            + ([f"topic = '${topic}'"] if topic else [])
        )
        return db.get_db().delete(
            cls.TABLENAME,
            where=where_clause,
            vars=data,
        )

    @classmethod
    def get_leaderboard(cls):
        """Returns the leaderboard of best books, aggregated as work_id plus
        award count, ordered by count descending."""
        query = f"""
            SELECT work_id, COUNT(*) AS award_count
            FROM {cls.TABLENAME}
            GROUP BY work_id
            ORDER BY award_count DESC
        """
        results = db.get_db().query(query)
        return [
            {"work_id": r["work_id"], "award_count": r["award_count"]}
            for r in results
        ]
