import React, { useEffect, useMemo, useState } from "react";
import { Room } from "matrix-js-sdk/src/models/room";
import { RoomMember } from "matrix-js-sdk/src/models/room-member";
import { logger } from "matrix-js-sdk/src/logger";

import { MatrixClientPeg } from "../../MatrixClientPeg";
import { getPrimaryPermalinkEntity, parsePermalink } from "../utils/permalinks/Permalinks";
import { PillType } from "../components/views/elements/Pill";
import { ButtonEvent } from "../components/views/elements/AccessibleButton";
import dis from "../dispatcher/dispatcher";
import { Action } from "../dispatcher/actions";
import RoomAvatar from "../components/views/avatars/RoomAvatar";
import MemberAvatar from "../components/views/avatars/MemberAvatar";

export interface UsePermalinkArgs {
    room?: Room;
    type?: PillType;
    url?: string;
}

export interface UsePermalinkResult {
    avatar: React.ReactElement | null;
    text: string | null;
    onClick: ((e: ButtonEvent) => void) | null;
    resourceId: string | null;
    type: PillType | "space" | null;
}

/**
 * A hook that resolves the information needed to render a Matrix permalink pill.
 *
 * Given a permalink `url` (and optional `type`/`room`), it returns the resolved
 * pill type, the raw resource id, the human-friendly display text, an optional
 * avatar element, and an optional click handler for user pills.
 *
 * If the permalink cannot be confidently resolved, the returned values lead the
 * consumer (Pill) to render nothing, preserving the "fail quiet" behaviour.
 */
export function usePermalink({ room, type, url }: UsePermalinkArgs): UsePermalinkResult {
    const [member, setMember] = useState<RoomMember | null>(null);
    const [resolvedRoom, setResolvedRoom] = useState<Room | null>(null);

    // Resolve the raw resource id and the effective pill type from the url sigil.
    const { resourceId, effectiveType } = useMemo(() => {
        let resourceId: string | null = null;
        let prefix: string | undefined;

        if (url) {
            if (room) {
                const parts = parsePermalink(url);
                resourceId = parts.primaryEntityId;
                prefix = parts.sigil;
            } else {
                resourceId = getPrimaryPermalinkEntity(url);
                prefix = resourceId ? resourceId[0] : undefined;
            }
        }

        const effectiveType =
            type ||
            ({
                "@": PillType.UserMention,
                "#": PillType.RoomMention,
                "!": PillType.RoomMention,
            } as Record<string, PillType>)[prefix];

        return { resourceId, effectiveType };
    }, [url, room, type]);

    // Resolve the room for room/alias pills, and the member for user pills.
    useEffect(() => {
        if (!effectiveType) {
            setResolvedRoom(null);
            setMember(null);
            return;
        }

        switch (effectiveType) {
            case PillType.AtRoomMention:
                setResolvedRoom(room ?? null);
                setMember(null);
                break;
            case PillType.UserMention:
                setResolvedRoom(null);
                if (resourceId) {
                    const localMember = room?.getMember(resourceId);
                    if (localMember) {
                        setMember(localMember);
                    } else {
                        const emptyMember = new RoomMember(null, resourceId);
                        setMember(emptyMember);
                        MatrixClientPeg.get()
                            .getProfileInfo(resourceId)
                            .then((resp) => {
                                emptyMember.name = resp.displayname;
                                emptyMember.rawDisplayName = resp.displayname;
                                setMember(emptyMember);
                            })
                            .catch((err) => {
                                logger.error("Could not retrieve profile data for " + resourceId + ":", err);
                            });
                    }
                }
                break;
            case PillType.RoomMention:
                setMember(null);
                if (resourceId) {
                    const client = MatrixClientPeg.get();
                    const localRoom =
                        resourceId[0] === "#"
                            ? client
                                  .getRooms()
                                  .find((r) => r.getCanonicalAlias() === resourceId || r.getAltAliases().includes(resourceId))
                            : client.getRoom(resourceId);
                    setResolvedRoom(localRoom ?? null);
                }
                break;
        }
    }, [effectiveType, resourceId, room]);

    // Build the avatar element based on the pill type and the shouldShowPillAvatar flag.
    const avatar = useMemo(() => {
        if (!effectiveType) {
            return null;
        }
        switch (effectiveType) {
            case PillType.AtRoomMention:
                return room ? <RoomAvatar room={room} width={16} height={16} aria-hidden="true" /> : null;
            case PillType.UserMention:
                return member ? (
                    <MemberAvatar member={member} width={16} height={16} aria-hidden="true" hideTitle />
                ) : null;
            case PillType.RoomMention:
                return resolvedRoom ? (
                    <RoomAvatar room={resolvedRoom} width={16} height={16} aria-hidden="true" />
                ) : null;
            default:
                return null;
        }
    }, [effectiveType, room, member, resolvedRoom]);

    // Build the human-friendly display text.
    const text = useMemo(() => {
        if (!effectiveType) {
            return null;
        }
        switch (effectiveType) {
            case PillType.AtRoomMention:
                return "@room";
            case PillType.UserMention:
                return member ? member.rawDisplayName || member.userId || resourceId : resourceId;
            case PillType.RoomMention:
                return resolvedRoom ? resolvedRoom.name || resourceId : resourceId;
            default:
                return resourceId;
        }
    }, [effectiveType, member, resolvedRoom, resourceId]);

    // The click handler is only relevant for user pills.
    const onClick = useMemo(() => {
        if (effectiveType === PillType.UserMention && member) {
            return (e: ButtonEvent) => {
                e.preventDefault();
                dis.dispatch({
                    action: Action.ViewUser,
                    member,
                });
            };
        }
        return null;
    }, [effectiveType, member]);

    // The resolved type, promoting room pills to "space" when the room is a Space.
    const resolvedType = useMemo(() => {
        if (!effectiveType) {
            return null;
        }
        if (effectiveType === PillType.RoomMention && resolvedRoom?.isSpaceRoom()) {
            return "space" as const;
        }
        return effectiveType;
    }, [effectiveType, resolvedRoom]);

    return {
        avatar,
        text,
        onClick,
        resourceId,
        type: resolvedType,
    };
}
