import React from "react";
import classNames from "classnames";
import { Room } from "matrix-js-sdk/src/models/room";
import { RoomMember } from "matrix-js-sdk/src/models/room-member";
import { logger } from "matrix-js-sdk/src/logger";
import { MatrixClient } from "matrix-js-sdk/src/client";
import { MatrixEvent } from "matrix-js-sdk/src/models/event";

import dis from "../../../dispatcher/dispatcher";
import { MatrixClientPeg } from "../../../MatrixClientPeg";
import { getPrimaryPermalinkEntity, parsePermalink } from "../../../utils/permalinks/Permalinks";
import MatrixClientContext from "../../../contexts/MatrixClientContext";
import { Action } from "../../../dispatcher/actions";
import Tooltip, { Alignment } from "./Tooltip";
import RoomAvatar from "../avatars/RoomAvatar";
import MemberAvatar from "../avatars/MemberAvatar";
import { objectHasDiff } from "../../../utils/objects";
import { ButtonEvent } from "./AccessibleButton";

export enum PillType {
    UserMention = "TYPE_USER_MENTION",
    RoomMention = "TYPE_ROOM_MENTION",
    AtRoomMention = "TYPE_AT_ROOM_MENTION", // '@room' mention
}

interface IProps {
    // The Type of this Pill. If url is given, this is auto-detected.
    type?: PillType;
    // The URL to pillify (no validation is done)
    url?: string;
    // Whether the pill is in a message
    inMessage?: boolean;
    // The room in which this pill is being rendered
    room?: Room;
    // Whether to include an avatar in the pill
    shouldShowPillAvatar?: boolean;
}

/**
 * Returns the position of the substring "@room" in the given text, or -1 if not present.
 */
export function pillRoomNotifPos(text: string): number {
    return text.indexOf("@room");
}

/**
 * Returns the length of the literal string "@room" (5).
 */
export function pillRoomNotifLen(): number {
    return "@room".length;
}

export function Pill(props: IProps): JSX.Element | null {
    const { type, url, inMessage, room, shouldShowPillAvatar } = props;

    const { avatar: avatarRaw, text, onClick, resourceId, type: resolvedType } = usePermalink({ room, type, url });

    // If we cannot confidently resolve a target entity, render nothing.
    if (!resolvedType || text === null) {
        return null;
    }

    const [hover, setHover] = useState(false);

    const avatar = shouldShowPillAvatar ? avatarRaw : null;

    let pillClass: string;
    let userId: string | null = null;
    let classes: string;

    switch (resolvedType) {
        case PillType.AtRoomMention:
            pillClass = "mx_AtRoomPill";
            break;
        case PillType.UserMention:
            pillClass = "mx_UserPill";
            userId = resourceId;
            break;
        case PillType.RoomMention:
            pillClass = "mx_RoomPill";
            break;
        case "space":
            pillClass = "mx_SpacePill";
            break;
        default:
            pillClass = null;
    }

    classes = classNames("mx_Pill", pillClass, {
        mx_UserPill_me: userId !== null && userId === MatrixClientPeg.get().getUserId(),
    });

    const tip = hover && resourceId ? <Tooltip label={resourceId} alignment={Alignment.Right} /> : null;

    const content = (
        <>
            {avatar}
            <span className="mx_Pill_linkText">{text}</span>
            {tip}
        </>
    );

    const onMouseOver = () => setHover(true);
    const onMouseLeave = () => setHover(false);

    const matrixClient = MatrixClientPeg.get();

    return (
        <bdi>
            <MatrixClientContext.Provider value={matrixClient}>
                {inMessage ? (
                    <a className={classes} href={url} onClick={onClick} onMouseOver={onMouseOver} onMouseLeave={onMouseLeave}>
                        {content}
                    </a>
                ) : (
                    <span className={classes} onMouseOver={onMouseOver} onMouseLeave={onMouseLeave}>
                        {content}
                    </span>
                )}
            </MatrixClientContext.Provider>
        </bdi>
    );
}
